def contains(node, target):
    """Recursively search for a target value in the BST."""
    # Base case: we reached a leaf's child, so the target isn't here
    if node is None:
        return False

    # Base case: we found the target!
    if node.value == target:
        return True

    # If the target is smaller, we only need to search the left subtree
    if target < node.value:
        return contains(node.left, target)

    # Otherwise, the target must be in the right subtree
    return contains(node.right, target)

