# 1. Define the Strategy Interface
class AggregationStrategy(ABC):
    @abstractmethod
    def execute(self, values: List[float]) -> float:
        pass

# 2. Implement Concrete Strategies
class SumStrategy(AggregationStrategy):
    def execute(self, values: List[float]) -> float:
        return sum(values)

class WeightedAverageStrategy(AggregationStrategy):
    """A strategy that requires internal state/configuration."""
    def __init__(self, weights: List[float]):
        self.weights = weights

    def execute(self, values: List[float]) -> float:
        if len(self.weights) != len(values):
            raise ValueError("Mismatched weights and values")
        return sum(v * w for v, w in zip(values, self.weights)) / sum(self.weights)

