    def __init__(self, strategy: AggregationStrategy):
        self._strategy = strategy

    def set_strategy(self, strategy: AggregationStrategy):
        """Allows changing the strategy at runtime."""
        self._strategy = strategy

    def calculate(self, values: List[float]) -> Optional[float]:
        if not values:
            return None
        return self._strategy.execute(values)

