class Directory(FileSystemComponent):
    """The Composite class represents complex components that may have children."""
    def __init__(self, name: str):
        self.name = name
        self.children: List[FileSystemComponent] = []

    def add(self, component: FileSystemComponent):
        self.children.append(component)

    def size(self) -> int:
        # A directory computes the sum of its children's sizes
        return sum(child.size() for child in self.children)

class LazyImage:
    def __init__(self, path):
        self.path = path
        self._image = None

    def display(self):
        if self._image is None:
            # We defer the expensive load_image call until display is actually invoked
            self._image = load_image(self.path)

        return self._image.display()

class Counter:
    def __init__(self, limit):
        self.current = 0
        self.limit = limit

    def __iter__(self):
        return self

    def __next__(self):
        if self.current >= self.limit:
            raise StopIteration

        value = self.current
        self.current += 1
        return value

def counter(limit):
    for i in range(limit):
